"""Probe: defect1 sequential batch. Generated by make_probes.py - do not hand-edit.
"""
import asyncio

from wire_kit import (BULLETIN_SYSTEM, MODEL, NOTE_SYSTEM, SUMMARY_SYSTEM,
                      URGENCY_SYSTEM, desk_prompt, make_async_client,
                      story_prompt)


async def _ask(client, system, user):
    """One completion. Returns the assistant text, stripped."""
    resp = await client.chat.completions.create(
        model=MODEL,
        messages=[{"role": "system", "content": system},
                  {"role": "user", "content": user}],
    )
    return (resp.choices[0].message.content or "").strip()


# --- 1. one after another: the values are right, the waits are not --------
async def summarise_batch(story_ids):
    out = []
    async with make_async_client() as client:
        for sid in story_ids:
            out.append(await _ask(client, SUMMARY_SYSTEM, story_prompt(sid)))
    return out

# --- 2. score them, but never more than `limit` at a time -----------------
async def rank_urgency(story_ids, limit):
    """Rank the stories by the score the desk returns, hardest push first."""
    gate = asyncio.Semaphore(limit)

    async def score(client, sid):
        # Only the call itself holds a slot; everything else runs free.
        async with gate:
            raw = await _ask(client, URGENCY_SYSTEM, story_prompt(sid))
        try:
            return float(raw.split()[0])
        except (ValueError, IndexError):
            return 0.0

    async with make_async_client() as client:
        scores = await asyncio.gather(*(score(client, sid)
                                        for sid in story_ids))

    # sorted() is stable, so stories on the same score keep the order they
    # arrived in.
    return [sid for sid, _ in
            sorted(zip(story_ids, scores), key=lambda pair: -pair[1])]


# --- 3. one bad desk must not take the batch down -------------------------
async def gather_desk_notes(requests):
    """A note per request. A rejected desk becomes a value, not an exception."""
    async def one(client, item):
        story_id, desk = item["story_id"], item["desk"]
        try:
            note = await _ask(client, NOTE_SYSTEM,
                              desk_prompt(story_id, desk))
            return {"story_id": story_id, "desk": desk, "ok": True,
                    "note": note}
        except Exception as exc:
            # Localised here, so the siblings still finish and the caller gets
            # structured data back either way.
            return {"story_id": story_id, "desk": desk, "ok": False,
                    "error": "%s: %s" % (type(exc).__name__, exc)}

    async with make_async_client() as client:
        return list(await asyncio.gather(*(one(client, item)
                                           for item in requests)))


# --- 4. the bulletin, or the deadline ------------------------------------
async def bulletin_under_deadline(story_id, budget):
    """Give the desk `budget` seconds, then stop waiting and say so."""
    async with make_async_client() as client:
        try:
            text = await asyncio.wait_for(
                _ask(client, BULLETIN_SYSTEM, story_prompt(story_id)),
                timeout=budget)
        except asyncio.TimeoutError:
            return {"ok": False, "reason": "deadline"}
        return {"ok": True, "text": text}


# --- 5. the bulletin as it comes in --------------------------------------
async def stream_bulletin(story_id):
    """Yield the bulletin piece by piece, as the desk sends it."""
    async with make_async_client() as client:
        stream = await client.chat.completions.create(
            model=MODEL,
            messages=[{"role": "system", "content": BULLETIN_SYSTEM},
                      {"role": "user", "content": story_prompt(story_id)}],
            stream=True,
        )
        async for chunk in stream:
            piece = chunk.choices[0].delta.content or ""
            if piece:
                yield piece
